WITH latest AS (SELECT id, customer_id, opened_date FROM accounts QUALIFY RANK() OVER (PARTITION BY account_type, customer_id ORDER BY opened_date DESC NULLS LAST) = 1) SELECT DATE_TRUNC('WEEK', opened_date) AS week_start, COUNT(*) AS cnt, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT customer_id) AS distinct_customer_ids, COUNT(DISTINCT customer_id) AS distinct_customer_ids_2, GROUPING(DATE_TRUNC('WEEK', opened_date)) AS gid FROM latest GROUP BY ROLLUP (DATE_TRUNC('WEEK', opened_date)) ORDER BY distinct_customer_ids_2 DESC NULLS LAST;
